urlset:
{% load static %}

        {{ FRONTEND_HOST }}
        always
        1.0


        {{ FRONTEND_HOST }}/featured
        daily
        0.8


        {{ FRONTEND_HOST }}/recommended
        always
        0.8


        {{ FRONTEND_HOST }}/latest
        hourly
        0.9


        {{ FRONTEND_HOST }}/members
        daily
        0.5


        {{ FRONTEND_HOST }}/tags
        daily
        0.5


        {{ FRONTEND_HOST }}/categories
        weekly
        0.5


        {{ FRONTEND_HOST }}/history
        always
        0.3


        {{ FRONTEND_HOST }}/liked
        always
        0.3


        {{ FRONTEND_HOST }}/about
        monthly
        0.3


        {{ FRONTEND_HOST }}/tos
        monthly
        0.3


        {{ FRONTEND_HOST }}/contact
        never
        0.3


    {% for media_object in media %}

        {{ FRONTEND_HOST }}/view?m={{ media_object.friendly_token }}
        {% if media_object.edit_date %}
        {{ media_object.edit_date|date:"Y-m-d" }}
        {% endif %}
        weekly
        0.8

        {% if media_object.media_type == "video" and media_object.encoding_status == "success" %}

            {{ media_object.title|escape }}
            {{ media_object.description|striptags|escape|slice:":2000" }}
            {{ FRONTEND_HOST }}{{ media_object.poster_url }}

            {% if media_object.original_media_url %}
            {{ FRONTEND_HOST }}{{ media_object.original_media_url }}
            {% endif %}
            {{ FRONTEND_HOST }}/embed?m={{ media_object.friendly_token }}
            {{ media_object.duration }}
            {{ media_object.add_date|date:"Y-m-d\TH:i:s+00:00" }}

            {% if media_object.user %}
            {{ media_object.user.username|escape }}
            {% endif %}

            no

            {% with media_object.category.all as categories %}
                {% if categories %}
                    {% for category in categories|slice:":1" %}
                        {{ category.title|escape }}
                    {% endfor %}
                {% endif %}
            {% endwith %}

            {% if media_object.tags.all %}
                {{ media_object.tags.all|slice:":5"|join:", "|escape }}
            {% endif %}

        {% endif %}

    {% endfor %}

    {% for playlist_object in playlists %}

        {{ FRONTEND_HOST }}/playlists/{{ playlist_object.friendly_token }}
        {% if playlist_object.edit_date %}
        {{ playlist_object.edit_date|date:"Y-m-d" }}
        {% endif %}
        weekly
        0.6

    {% endfor %}

    {% for user_object in users %}

        {{ FRONTEND_HOST }}/user/{{ user_object.username }}/
        weekly
        0.4

    {% endfor %}
